(async function(){
  'use strict';
  const C=window.AtlasCore,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],e=C.esc;
  const defaults={page:'map',series:'handovers',region:'World',subregion:'',mechanism:'',group:'',coverage:'',precision:'',scenario:'main',timeMode:'all',month:C.FIRST_MONTH,search:'',country:'',colourBy:'mechanism'};
  let state={...defaults},data,methods,countryMap,matching=[],pageNumber=0,listLimit=12,sort='newest',playing=false,playTimer=null,activeCountry=null,countryTab='handovers',lastFocus=null,searchTimer,toastTimer;
  const regionNames=['World','Africa','Europe','Asia','North America','South America','Oceania'];
  const seriesName=()=>state.series==='collective'?'collective membership changes':'office & authority handovers';
  const mechanism=r=>(C.mechanisms[r.mechanism]||[r.mechanism?.replaceAll('_',' ')||'Unclassified','#7d8884']);
  const safeUrl=u=>/^https?:\/\//i.test(u||'')?e(u):'';
  function renderReleaseMetadata(){
    const m=data.meta,n=value=>value.toLocaleString('en-GB');
    $('#release-label').textContent='Research release · '+m.release;
    $('#release-label').title='Frozen '+C.date(m.researchDate);
    for(const[id,key,label]of [['download-handovers','totalHandovers','handovers'],['download-collective','totalCollectiveChanges','collective changes'],['download-cases','countryCases','geographic cases'],['download-questions','openQuestions','open questions']])$('#'+id).textContent=n(m[key])+' '+label;
    $('#coverage-view option[value="all"]').textContent='All '+n(m.countryCases)+' cases';
    $('#coverage-view option[value="partial"]').textContent=n(m.partialCases)+' partial cases';
    $('#coverage-view option[value="none"]').textContent=n(m.verifiedNoTransitionCases)+' verified no-transition cases';
    $$('[data-release-download]').forEach(a=>{a.title=m.release+' · '+C.date(m.researchDate);});
    $('meta[name="description"]').content=`Explore ${m.totalHandovers} verified political office and authority handovers and ${m.totalCollectiveChanges} collective membership changes across ${m.countryCases} geographic cases, 2016–2026. Research release ${m.release}, ${C.date(m.researchDate)}. A sourced historical atlas by Hugh Lamarque.`;
  }
  function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').hidden=true;},4500);}
  function download(text,name,type='text/csv;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function dateTag(r){return r.date_precision==='range'?'<span class="tag range">Date interval</span>':'';}
  function coverageTag(c){return c.coverage_status==='full_window_verified'?'<span class="tag">Full period checked</span>':'<span class="tag partial">Partial coverage</span>';}
  function shortHolder(r){const h=C.holder(r.incoming);return h.length>105?h.slice(0,102)+'…':h;}
  function recordCard(r){const m=mechanism(r),possible=C.relation(r,C.period(state))==='possible';return `<button class="event-card" style="--mechanism:${m[1]}" data-record="${e(C.id(r))}"><span class="event-card-top"><strong>${e(countryMap.get(r.country_code)?.country||r.country)}</strong><span>${e(C.id(r))}</span></span><span class="event-card-title">${e(shortHolder(r))}</span><span class="record-office">${e(r.office||r.collective_body)}</span><span class="record-date">${e(C.dateLabel(r))}</span>${possible?'<span class="tag range">May fall in this period</span>':dateTag(r)}</button>`;}
  function periodText(){if(state.timeMode==='all')return '11 Nov 2016–11 Nov 2026';if(state.timeMode==='year')return String(Math.floor(state.month/12));return C.monthLabel(state.month);}
  function filterText({ignoreTime=false}={}){return [ignoreTime?'Whole study window':periodText(),state.region,seriesName(),state.subregion,state.mechanism?(C.mechanisms[state.mechanism]?.[0]||state.mechanism.replaceAll('_',' ')):'',state.coverage==='partial_events_verified'?'Partial coverage only':state.coverage?'Full period checked only':'',state.group?C.groupLabels[state.group]:'',state.precision==='range'?'Date intervals only':state.precision?'Exact days only':'',state.search?`Search: “${state.search}”`:'',state.country?countryMap.get(state.country)?.country:'',state.scenario!=='main'?data.sensitivity.scenarios.find(s=>s.key===state.scenario)?.label:''].filter(Boolean).join(' · ');}
  function writeURL(extra={}){const p=new URLSearchParams();for(const k of Object.keys(defaults))if(state[k]!==defaults[k]&&state[k]!=='')p.set(k,String(state[k]));for(const[k,v]of Object.entries(extra))if(v)p.set(k,v);const q=p.toString();history.replaceState(null,'',location.pathname+(q?'?'+q:''));}
  function change(key,value){if(key==='page'){navigate(value);return;}state[key]=value;pageNumber=0;listLimit=12;if(key==='region'){state.subregion='';state.country='';AtlasMap.setRegion(value);}if(key==='timeMode'&&value==='all')stopPlay();render();}
  function navigate(page){if(!['map','overview','analysis','dataset'].includes(page))return;state.page=page;if(page!=='map')stopPlay();$$('.page').forEach(el=>el.hidden=el.id!==page+'-page');$$('.masthead [data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-pressed',String(b.dataset.page===page));});document.body.dataset.page=page;render();if(page==='map')requestAnimationFrame(()=>AtlasMap.invalidate());else window.scrollTo({top:0,behavior:'instant'});}
  function syncControls(){
    for(const[id,key]of Object.entries({'series':'series','analysis-series':'series','dataset-series':'series','time-mode':'timeMode','subregion':'subregion','mechanism':'mechanism','group':'group','coverage':'coverage','precision':'precision','scenario':'scenario','analysis-scenario':'scenario','analysis-region':'region','colour-by':'colourBy'}))$('#'+id).value=state[key];
    for(const id of ['search','mobile-search','dataset-search'])if(document.activeElement!==$('#'+id))$('#'+id).value=state.search;
    $('#month-slider').value=String(state.month-C.FIRST_MONTH);$('#month-slider').setAttribute('aria-valuetext',C.monthLabel(state.month));
    $('#date-button').innerHTML=e(state.timeMode==='all'?'All years':state.timeMode==='year'?String(Math.floor(state.month/12)):C.monthLabel(state.month))+' <span aria-hidden="true">⌄</span>';
    $('#previous').disabled=state.timeMode!=='all'&&state.month<=C.FIRST_MONTH;$('#next').disabled=state.timeMode!=='all'&&state.month>=C.LAST_MONTH;
    $$('.continent-tabs [data-region]').forEach(b=>{b.classList.toggle('active',b.dataset.region===state.region);b.setAttribute('aria-pressed',String(b.dataset.region===state.region));});
    $('#panel-title').textContent=state.region;$('#map-status').textContent=state.region+' · '+(state.timeMode==='all'?'All recorded changes':periodText());
    const active=['subregion','mechanism','group','coverage','precision'].filter(k=>state[k]).length+(state.scenario!=='main'?1:0);$('#filter-count').textContent=active?'('+active+')':'';
    $('#country-chip').hidden=!state.country;if(state.country)$('#country-chip span').textContent=countryMap.get(state.country)?.country||state.country;
  }
  function render(){
    if(!data)return;syncControls();matching=C.filter(data,state);writeURL();
    if(state.page==='map')renderMap();
    if(state.page==='analysis'){const records=C.filter(data,state,{ignoreTime:true});$('#analysis-filters').textContent=filterText({ignoreTime:true})+'. The map’s month/year selection does not restrict these charts.';AtlasAnalysis.render({data,records,series:state.series,onCountry:openCountry});}
    if(state.page==='dataset')renderDataset();
  }
  function renderMap(){
    $('#map').setAttribute('aria-label','World map of '+seriesName()+' · '+periodText());
    AtlasMap.update({records:matching,countries:data.countries,colourBy:state.colourBy,series:state.series,selectedCountry:activeCountry||state.country||null});
    const ranged=matching.filter(r=>r.date_precision==='range').length,possible=matching.filter(r=>C.relation(r,C.period(state))==='possible').length,nCountries=new Set(matching.map(r=>r.country_code)).size;
    $('#record-count').textContent=matching.length.toLocaleString('en-GB');$('#unit-label').textContent=state.series==='collective'?(matching.length===1?'collective change':'collective changes'):(matching.length===1?'handover':'handovers');$('#result-meta').innerHTML=nCountries+(nCountries===1?' country<br>':' countries<br>')+ranged+' with date intervals';
    $('#result-context').textContent=(state.series==='collective'?'Changes in the membership of governing bodies. Counted separately from office handovers.':'Changes in a tracked officeholder or governing authority. Several executive offices may be tracked in one country.')+(possible?` ${possible} record${possible===1?' has':'s have'} a date interval that only partly overlaps this period.`:'');
    const sorted=[...matching].sort((a,b)=>b.date_start.localeCompare(a.date_start)||C.id(a).localeCompare(C.id(b)));
    const zeroCountries=state.search?data.countries.filter(c=>C.normalise(c.country).includes(C.normalise(state.search))&&!matching.some(r=>r.country_code===c.country_code)):[];
    $('#event-list').innerHTML=sorted.slice(0,listLimit).map(recordCard).join('')+(zeroCountries.length?zeroCountries.slice(0,5).map(c=>`<button class="event-card" data-country="${e(c.country_code)}"><span class="event-card-title">${e(c.country)}</span><span class="record-office">${c.no_transition_verified?'Verified no-transition case in the study window':'No records match these filters'}</span><span class="record-date">View country coverage and sources →</span></button>`).join(''):'')+(!matching.length&&!zeroCountries.length?'<div class="empty-state">No records match these filters. This does not establish that no transition occurred. <button class="text-button" data-reset>Reset filters</button> or inspect country coverage in Dataset.</div>':'');
    $('#show-more').hidden=listLimit>=matching.length;$('#show-more').textContent=`Show more (${Math.min(listLimit,matching.length)} of ${matching.length})`;
    $('#timeline-note').textContent=state.timeMode==='all'?'11 Nov 2016–11 Nov 2026 · Dates show changes of authority.':(possible?`${possible} possible date overlaps · Intervals may appear in more than one period.`:periodText()+' · Events in this period; date intervals remain explicit.');
    renderLegend();
  }
  function legendHTML(){
    let items=[];
    if(state.colourBy==='count')items=[['#f5f6f4','0 in selection'],['#dcebe1','1–2 records'],['#a9ccbb','3–5 records'],['#609781','6–9 records'],['#244e46','10+ records'],['#e9ede8','Outside study frame']];
    else if(state.colourBy==='mechanism')items=[...Object.values(C.mechanisms).map(([l,c])=>[c,l]),[AtlasMap.stripeGradient(AtlasMap.mechanisms.multiple.colours),'Multiple mechanisms'],['#f5f6f4','0 in selection']];
    else items=[['#a9ccbb','Full period checked'],['#ead7b3','Partial coverage'],['#e9ede8','Outside study frame']];
    return '<div class="legend-grid">'+items.map(([color,label])=>`<span class="legend-item"><i class="swatch" style="background:${color}"></i>${e(label)}</span>`).join('')+'</div>';
  }
  function legendNote(){return state.colourBy==='coverage'?`Coverage refers to the full study period for all ${data.meta.countryCases} cases, regardless of record filters. Country details explain any remaining gaps. Small circles help select small states.`:(state.colourBy==='count'?'Colour shows the number of selected records.':'Diagonal stripes show the mechanisms present in the selected records. Equal widths indicate presence, not proportions.')+' Country details explain coverage and evidence gaps. A zero is not proof of no transitions. Small circles make small states easier to select.';}
  function renderLegend(){$('#legend').innerHTML=legendHTML();$('#key-note').textContent=legendNote();}
  function showDialog(dialog){lastFocus=document.activeElement;if(!dialog.open)dialog.showModal();dialog.querySelector('[data-close]')?.focus();}
  function closeDialog(dialog){dialog.close();if(dialog.id==='country-dialog'){activeCountry=null;writeURL();if(state.page==='map')renderMap();}if(dialog.id==='record-dialog')writeURL(activeCountry?{case:activeCountry}:{});lastFocus?.focus?.();}
  function sourcesHTML(sources){const s=(sources||[]).filter(s=>safeUrl(s.url));return s.length?'<ol class="source-list">'+s.map(s=>`<li><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title||new URL(s.url).hostname)} ↗</a><small>${e([s.publisher,s.published_date?C.date(s.published_date):''].filter(Boolean).join(' · '))}</small></li>`).join('')+'</ol>':'<p class="muted">See the office sequence and research workbook for the retained source evidence.</p>';}
  function chainCoverageHTML(ch){
    const status=ch.in_scope===false?'Outside definition':String(ch.coverage_status).startsWith('full')?'Full period checked':String(ch.coverage_status).startsWith('partial')?'Partial coverage':'Scope unresolved';
    const notes=[...new Set([ch.scope_notes,ch.continuity_notes,ch.sequence_notes].flat().filter(x=>typeof x==='string'&&x.trim()))];
    const gaps=[...new Set([ch.remaining_gaps,ch.gaps,ch.residual_uncertainties,ch.endpoint_limitation].flat().filter(x=>typeof x==='string'&&x.trim()))];
    const facts=[
      ['Opening holder',ch.opening_holder==null?null:C.holder(ch.opening_holder)],
      ['Closing holder',ch.closing_holder==null?null:C.holder(ch.closing_holder)],
      ['Executive role begins',ch.office_start||ch.tracked_from],
      ['Executive role ends',ch.office_end||ch.tracked_until],
      ['Sequence checked through',ch.sequence_checked_through],
      ['Latest dated holder evidence',ch.latest_holder_evidence_date]
    ].filter(([,value])=>value);
    return `<details class="coverage-detail"><summary>${e(ch.office||ch.office_key)} <span class="tag ${String(ch.coverage_status).startsWith('partial')?'partial':''}">${status}</span></summary>${facts.length?'<dl class="record-definition">'+facts.map(([label,value])=>'<dt>'+e(label)+'</dt><dd>'+e(/^\d{4}-\d{2}-\d{2}$/.test(value)?C.date(value):value)+'</dd>').join('')+'</dl>':''}${notes.map(note=>'<p>'+e(note)+'</p>').join('')}${gaps.length?'<div class="coverage-note"><strong>Unresolved evidence</strong><ul>'+gaps.map(gap=>'<li>'+e(gap)+'</li>').join('')+'</ul></div>':''}${sourcesHTML(ch.sources)}</details>`;
  }
  function openRecord(id){
    const r=[...data.events,...data.collective].find(r=>C.id(r)===id);if(!r)return;stopPlay();
    $('#record-title').textContent=r.office||r.collective_body||'Governing authority';$('#record-subtitle').textContent=(countryMap.get(r.country_code)?.country||r.country)+' · '+C.id(r)+' · '+(r.event_id?'Office / authority handover':'Collective membership change');
    const m=mechanism(r),c=countryMap.get(r.country_code),caveats=Array.isArray(r.caveats)?r.caveats:r.caveats?[r.caveats]:[],flags=data.sensitivity.flags.filter(f=>f.record_id===id),authority=r.authority_status==='de_jure_and_effective'?'Legal and effective authority':(r.authority_status||'See source evidence').replaceAll('_',' ');
    $('#record-body').innerHTML=`<div class="record-meta">${coverageTag(c)}${dateTag(r)}<span class="tag" style="border-left:3px solid ${m[1]}">${e(m[0])}</span></div><div class="record-date-line">${e(C.dateLabel(r))}${r.date_precision==='range'?'<p class="muted" style="font-size:12px;font-weight:400;margin:7px 0 0">The event occurred within this supported interval; an exact day has not been established.</p>':''}</div><p>${e(r.summary)}</p><div class="handover-flow"><div><small>Outgoing</small><strong>${e(C.holder(r.outgoing))}</strong></div><span class="arrow" aria-hidden="true">→</span><div><small>Incoming</small><strong>${e(C.holder(r.incoming))}</strong></div></div><dl class="record-definition"><dt>Mechanism</dt><dd>${e(m[0])}</dd><dt>Governing group</dt><dd>${e(C.groupLabels[r.governing_group_change]||'Unclear')}</dd><dt>Authority</dt><dd>${e(authority)}</dd><dt>Why this date</dt><dd>${e(r.date_basis||'See source evidence.')}</dd></dl>${caveats.length?'<details class="record-caveats" open><summary>Context &amp; uncertainty</summary><ul>'+caveats.map(x=>'<li>'+e(x)+'</li>').join('')+'</ul></details>':''}${flags.length?'<details class="record-caveats"><summary>Why alternative definitions affect this record</summary>'+flags.map(f=>'<p>'+e(f.reason)+'</p>').join('')+'</details>':''}<section class="record-evidence"><h3>Source evidence</h3>${sourcesHTML(r.sources)}</section><p class="evidence-note">Research release ${e(data.meta.release)}. Coverage describes the completeness of the country sequence; date precision describes when this event occurred. An unidentified holder does not establish a vacancy.</p><button class="quiet" data-country="${e(r.country_code)}">View ${e(c.country)}’s full sequence →</button>`;
    showDialog($('#record-dialog'));writeURL({case:activeCountry,record:id});
  }
  function openCountry(code){
    const c=countryMap.get(code);if(!c)return;stopPlay();if($('#record-dialog').open)$('#record-dialog').close();activeCountry=code;countryTab=state.series==='collective'?'collective':'handovers';
    $('#country-title').textContent=c.country;$('#country-subtitle').textContent=[c.subregion,c.frame_group].filter(Boolean).join(' · ');
    $('#country-intro').innerHTML=coverageTag(c)+(c.no_transition_verified?'<span class="tag no-transition">Verified no-transition case</span>':'')+`<p><strong>${c.verified_event_count} ${c.verified_event_count===1?'handover':'handovers'}</strong> · <strong>${c.verified_structural_change_count} collective ${c.verified_structural_change_count===1?'change':'changes'}</strong> · 11 Nov 2016–11 Nov 2026</p><p>This country view shows the full study period and uses the adopted definition, regardless of the map filters.</p>`+countryCoverageNotice(c);
    renderCountry();showDialog($('#country-dialog'));writeURL({case:code});if(state.page==='map')AtlasMap.update({records:matching,countries:data.countries,colourBy:state.colourBy,series:state.series,selectedCountry:code});
  }
  function countryCoverageNotice(c){
    if(!c.coverage_status.startsWith('partial'))return '';
    const reviewed=window.AtlasCoverageNotes;
    const summary=(reviewed?.release===data.meta.release?reviewed.summaries[c.country_code]:null)||c.remaining_work||'Some parts of the governing-authority sequence still need evidence. See the coverage details for the outstanding questions.';
    return `<aside class="country-coverage-notice" aria-labelledby="country-coverage-heading"><h3 id="country-coverage-heading">Why coverage is partial</h3><p>${e(summary)}</p><button class="text-button" data-country-tab="coverage">Read coverage details &amp; sources →</button></aside>`;
  }
  function renderCountry(){
    const c=countryMap.get(activeCountry);if(!c)return;$$('.country-tabs [data-country-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.countryTab===countryTab);b.setAttribute('aria-pressed',String(b.dataset.countryTab===countryTab));});
    if(countryTab==='coverage'){
      const chains=c.office_chains||[],questions=c.open_questions||[];
      $('#country-body').innerHTML=`<h3>What has been checked</h3><p>${e(c.notes||'See the office sequences below for scope and coverage.')}</p>${c.remaining_work?`<div class="coverage-note"><strong>${c.coverage_status.startsWith('partial')?'Remaining evidence gaps':'Coverage assessment'}</strong><br>${e(c.remaining_work)}</div>`:''}${c.no_transition_verified?'<div class="coverage-note">This country has a separately supported no-transition finding under the study definition. It is not inferred from a zero on the map.</div>':''}<h3>Tracked office sequences</h3>${chains.map(chainCoverageHTML).join('')}<h3 style="margin-top:25px">Open questions (${questions.length})</h3>${questions.length?questions.map(q=>`<details class="coverage-detail"><summary>${e(q.type?.replaceAll('_',' ')||q.case_id||'Evidence question')}</summary><p>${e(q.reason||q.required_action)}</p>${q.required_action&&q.required_action!==q.reason?'<p><strong>Next evidence needed:</strong> '+e(q.required_action)+'</p>':''}${sourcesHTML(q.sources)}</details>`).join(''):'<p class="muted">No open follow-up question is retained for this country in this release.</p>'}<h3 style="margin-top:25px">Country and scope sources</h3>${sourcesHTML(c.sources)}`;
    }else{
      const records=(countryTab==='collective'?data.collective:data.events).filter(r=>r.country_code===activeCountry).sort((a,b)=>a.date_start.localeCompare(b.date_start)||C.id(a).localeCompare(C.id(b)));
      $('#country-body').innerHTML=records.length?records.map(r=>`<article class="country-record" style="--mechanism:${mechanism(r)[1]}"><p class="record-date">${e(C.dateLabel(r))} ${dateTag(r)}</p><h3>${e(r.office||r.collective_body)}</h3><div class="succession">${e(C.holder(r.outgoing))} → <strong>${e(C.holder(r.incoming))}</strong></div><p>${e(r.summary)}</p><span class="tag">${e(mechanism(r)[0])}</span> <button class="text-button" data-record="${e(C.id(r))}">Read record &amp; sources →</button></article>`).join(''):`<div class="empty-state">${c.no_transition_verified?'The country has a verified no-transition finding for the study window.':'No '+(countryTab==='collective'?'collective membership changes':'office or authority handovers')+' are recorded for this country in this release. '+(c.coverage_status.startsWith('partial')?'Coverage remains partial; the absence of a record is not a no-transition finding.':'Check the other series and the documented office scope.')} <button class="text-button" data-country-tab="coverage">Read coverage evidence</button></div>`;
    }
  }
  function renderOverview(){
    const o=methods.overview;$('#overview-content').innerHTML=`<header class="reading-head"><div><p class="eyebrow">${e(o.eyebrow)}</p><h2>A decade of changes in power</h2><p>${e(o.introduction)}</p></div><button class="quiet" data-navigate="map">Explore the map →</button></header><div class="metric-grid">${o.cards.map(c=>`<section class="metric-card"><strong>${c.value}</strong><h3>${e(c.label)}</h3><p>${e(c.detail)}</p></section>`).join('')}</div><div class="coverage-note">${e(o.release_note)}<br>${e(o.interpretation)}</div><div class="overview-grid"><section><p class="eyebrow">Start with the map</p><h3>Follow a country’s sequence</h3><p>Select a country to read its handovers in chronological order, including the outgoing and incoming holders, the mechanism and the source evidence. Use Views &amp; records to search leaders, choose a region and refine the register.</p><p>Play the timeline to move month by month. A pale country has no matching record in the selection. Country details explain any gaps in the full-period sequence.</p><button class="quiet" data-navigate="map">Open the atlas →</button><p>Compare annual mechanism counts by continent: <button class="text-button" data-navigate="analysis">Mechanisms over time →</button></p></section><section><p class="eyebrow">Read the evidence</p><h3>Keep uncertainty in view</h3><p>Handovers and collective membership changes use different counting units. Date intervals remain intervals. Verified records can belong to a country whose overall sequence still has gaps.</p><p>The dataset records ${data.meta.fullWindowCases} full-period checks, ${data.meta.partialCases} partial cases, ${data.meta.openQuestions} open follow-up questions and ${data.meta.heldCandidates} held event candidates. Held candidates await sufficient evidence and are excluded from the totals.</p><button class="quiet" data-navigate="dataset">Explore records &amp; downloads →</button></section></div><h2 class="section-heading" id="methods">Scope &amp; methods</h2><div class="methods-list">${methods.methods.map((s,i)=>`<details id="method-${e(s.id)}" ${i===0?'open':''}><summary>${e(s.title)}</summary><div class="methods-body">${s.paragraphs.map(p=>'<p>'+e(p)+'</p>').join('')}</div></details>`).join('')}<details><summary>Mechanism categories</summary><div class="methods-body definition-grid">${methods.mechanisms.map(m=>`<div><h4>${e(m.label)}</h4><p>${e(m.definition)}</p></div>`).join('')}</div></details><details><summary>Governing-group change</summary><div class="methods-body definition-grid">${methods.governing_group.map(m=>`<div><h4>${e(m.label)}</h4><p>${e(m.definition)}</p></div>`).join('')}</div></details><details><summary>How alternative definitions change the count</summary><div class="methods-body"><p>${e(methods.sensitivity.introduction)}</p><div class="table-wrap"><table><thead><tr><th>Definition</th><th class="numeric">Handovers</th><th class="numeric">Collective changes</th></tr></thead><tbody>${data.sensitivity.scenarios.map(s=>`<tr><td>${e(s.label)}</td><td class="numeric">${s.handovers}</td><td class="numeric">${s.collective_changes}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:15px">These are alternative scope choices, not estimates of undiscovered events. Select a definition under Filters to apply its record exclusions to the map, charts and exports.</p></div></details></div><section class="citation"><h3>Cite this atlas</h3><p>${e(methods.citation.suggested_text)} <span class="citation-url">${e(location.origin+location.pathname)}</span>. Include your access date.</p><p>Mapping by Hugh Lamarque. The interface follows the <a href="https://lamarque-mapping.github.io/Border-Closure-Atlas/" target="_blank" rel="noopener">Border Closure Atlas</a>. Base geography: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth</a>; map library: <a href="https://leafletjs.com/" target="_blank" rel="noopener">Leaflet</a>. Country reference points locate records for browsing, not the precise location of an event.</p><p>Research and source review used separate GPT-6 Astra Pro contexts. The methods and workbook explain the review process and remaining gaps.</p></section>`;
  }
  function renderDataset(){
    let records=[...matching];records.sort(sort==='country'?(a,b)=>(countryMap.get(a.country_code)?.country||a.country).localeCompare(countryMap.get(b.country_code)?.country||b.country)||a.date_start.localeCompare(b.date_start):sort==='oldest'?(a,b)=>a.date_start.localeCompare(b.date_start):(a,b)=>b.date_start.localeCompare(a.date_start));
    const max=Math.max(0,Math.ceil(records.length/25)-1);pageNumber=Math.min(pageNumber,max);const start=pageNumber*25;
    $('#dataset-summary').textContent=records.length+' matching '+seriesName()+' · '+filterText()+'. Downloads above contain the unfiltered register; “Download matching CSV” uses these filters.';
    $('#dataset-list').innerHTML=records.length?records.slice(start,start+25).map(r=>`<button class="dataset-row" data-record="${e(C.id(r))}" style="--mechanism:${mechanism(r)[1]}"><div><h3>${e(countryMap.get(r.country_code)?.country||r.country)}</h3><small>${e(C.id(r))}</small><div class="record-date">${e(C.dateLabel(r))}</div>${dateTag(r)}</div><div><h3>${e(shortHolder(r))}</h3><p>${e(r.summary)}</p><small>${e(r.office||r.collective_body)}</small></div><div class="data-mechanism">${e(mechanism(r)[0])}<small>${(r.sources||[]).length} source links · Read record →</small></div></button>`).join(''):'<div class="empty-state">No records match the active filters. Reset filters to return to the full register.</div>';
    $('#data-page-label').textContent=records.length?`${start+1}–${Math.min(start+25,records.length)} of ${records.length}`:'0 records';$('#data-previous').disabled=pageNumber===0;$('#data-next').disabled=pageNumber>=max;renderCoverage();
  }
  function renderCoverage(){const filter=$('#coverage-view').value;const cases=[...data.countries].filter(c=>filter==='partial'?c.coverage_status.startsWith('partial'):filter==='none'?c.no_transition_verified:true).sort((a,b)=>a.country.localeCompare(b.country));$('#coverage-list').innerHTML=cases.map(c=>`<button class="coverage-country" data-country="${e(c.country_code)}"><span>${e(c.country)}</span>${c.no_transition_verified?'<span class="tag no-transition">No transition verified</span>':coverageTag(c)}</button>`).join('');}
  function help(type){
    const main=data.sensitivity.scenarios.find(s=>s.key==='main'),strict=data.sensitivity.scenarios.find(s=>s.key==='strict');
    const sensitivityHTML='<p>These options exclude specified types of office or event:</p><ul>'+Object.values(data.sensitivity.categories).map(label=>'<li>'+e(label)+'</li>').join('')+'</ul><p>The adopted definition contains '+main.handovers+' handovers and '+main.collective_changes+' collective changes. Applying all listed narrower choices gives '+strict.handovers+' handovers and '+strict.collective_changes+' collective changes. These are different definitions, not estimates of missing events.</p>';
    const helpText={mechanism:['Mechanism categories','<p>Each record has one primary mechanism classification. When a country has several mechanisms in the current selection, diagonal stripes show their colours at equal widths. The stripes show presence, not the proportion of records. The transfer date can differ from the election or announcement. Each record explains the circumstances and any uncertainty.</p><div class="definition-grid">'+methods.mechanisms.map(m=>'<div><h4>'+e(m.label)+'</h4><p>'+e(m.definition)+'</p></div>').join('')+'</div>'],group:['Governing-group change','<p>A change of officeholder does not establish a new governing party, coalition or regime. “Unclear” is distinct from continuity.</p>'+methods.governing_group.map(g=>'<p><strong>'+e(C.groupLabels[g.code])+':</strong> '+e(g.definition)+'</p>').join('')],sensitivity:['Alternative definitions',sensitivityHTML],map:['Reading the map','<label class="stack-field">Colour by<select id="mobile-colour-by"><option value="mechanism">Mechanism</option><option value="count">Number of records</option><option value="coverage">Research coverage</option></select></label><div id="dialog-map-legend">'+legendHTML()+'<p>'+e(legendNote())+'</p></div><p>All '+data.meta.countryCases+' geographic cases remain selectable. Full-period checks and partial coverage concern the research sequence, not the character of a political system. Map borders do not imply a position on recognition or territorial claims.</p>']};
    const content=helpText[type];if(!content)return;$('#help-title').textContent=content[0];$('#help-body').innerHTML=content[1];showDialog($('#help-dialog'));if(type==='map'){$('#mobile-colour-by').value=state.colourBy;$('#mobile-colour-by').onchange=ev=>{change('colourBy',ev.target.value);$('#dialog-map-legend').innerHTML=legendHTML()+'<p>'+e(legendNote())+'</p>';};}
  }
  function cite(){$('#help-title').textContent='Cite the atlas';$('#help-body').innerHTML='<p>'+e(methods.citation.suggested_text)+'</p><p>'+e(location.origin+location.pathname)+'. Include your access date.</p><p class="muted">Mapping by Hugh Lamarque. Record-specific sources are linked in each entry.</p><button class="quiet" id="copy-citation">Copy citation</button>';showDialog($('#help-dialog'));$('#copy-citation').onclick=async()=>{try{await navigator.clipboard.writeText(methods.citation.suggested_text+' '+location.origin+location.pathname);toast('Citation copied.');}catch{toast('Select and copy the citation shown above.');}};}
  function stopPlay(){playing=false;clearTimeout(playTimer);$('#play').setAttribute('aria-label','Play timeline');$('#play-text').textContent='Play timeline';$('#play>span:first-child').textContent='▶︎';}
  function tick(){if(!playing)return;if(state.month>=C.LAST_MONTH){stopPlay();return;}playTimer=setTimeout(()=>{if(!playing)return;state.month++;render();tick();},1200/Number($('#speed').value));}
  function togglePlay(){if(playing){stopPlay();return;}if(state.timeMode==='all'||state.month>=C.LAST_MONTH)state.month=C.FIRST_MONTH;state.timeMode='month';playing=true;$('#play').setAttribute('aria-label','Pause timeline');$('#play-text').textContent='Pause';$('#play>span:first-child').textContent='Ⅱ';render();tick();}
  function reset(){stopPlay();const page=state.page;state={...defaults,page};pageNumber=0;listLimit=12;for(const i of ['search','mobile-search','dataset-search'])$('#'+i).value='';AtlasMap.setLabels(false);$('#labels-toggle').setAttribute('aria-pressed','false');AtlasMap.setRegion('World');render();}
  function togglePanel(open){const mobile=matchMedia('(max-width:760px)').matches;$('#map-page').classList.toggle('panel-open',open);$('#map-page').classList.toggle('sidebar-collapsed',!open&&!mobile);$('#panel-toggle').setAttribute('aria-expanded',String(open));}
  function attach(){
    document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.record)openRecord(b.dataset.record);else if(b.dataset.country)openCountry(b.dataset.country);else if(b.dataset.countryTab){countryTab=b.dataset.countryTab;renderCountry();}else if(b.dataset.navigate)navigate(b.dataset.navigate);else if(b.hasAttribute('data-reset'))reset();else if(b.hasAttribute('data-export'))download(C.csv(matching),'Political_Transitions_'+state.series+'_filtered.csv');else if(b.hasAttribute('data-help')){ev.preventDefault();ev.stopPropagation();help(b.dataset.help);}else if(b.hasAttribute('data-cite'))cite();else if(b.hasAttribute('data-close'))closeDialog(b.closest('dialog'));});
    $$('.masthead [data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$$('[data-region]').forEach(b=>b.onclick=()=>change('region',b.dataset.region));
    for(const[id,key]of Object.entries({'series':'series','analysis-series':'series','dataset-series':'series','time-mode':'timeMode','subregion':'subregion','mechanism':'mechanism','group':'group','coverage':'coverage','precision':'precision','scenario':'scenario','analysis-scenario':'scenario','analysis-region':'region','colour-by':'colourBy'}))$('#'+id).onchange=ev=>change(key,ev.target.value);
    for(const id of ['search','mobile-search','dataset-search'])$('#'+id).oninput=ev=>{const value=ev.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>change('search',value),180);};
    $('#clear-country').onclick=()=>change('country','');$('#show-more').onclick=()=>{listLimit+=24;renderMap();};$('#panel-toggle').onclick=()=>togglePanel(true);$('#collapse-panel').onclick=()=>togglePanel(false);
    $('#read-records').onclick=()=>navigate('dataset');$('#labels-toggle').onclick=ev=>{const on=ev.currentTarget.getAttribute('aria-pressed')!=='true';ev.currentTarget.setAttribute('aria-pressed',String(on));AtlasMap.setLabels(on);};$('#key-toggle').onclick=()=>help('map');$('#fit-records').onclick=()=>AtlasMap.fitRecords(matching);
    $('#save-view').onclick=async()=>{const b=$('#save-view');b.disabled=true;b.textContent='Saving…';try{await AtlasMap.exportPNG({title:'Political Transitions Atlas',subtitle:filterText(),credit:'Hugh Lamarque · '+data.meta.release+', '+C.date(data.meta.researchDate)+' · Reference geography: Natural Earth'});toast('Map view saved as a PNG.');}catch(err){toast('The map image could not be saved. Please try again.');console.error(err);}finally{b.disabled=false;b.textContent='Save view';}};
    $('#play').onclick=togglePlay;$('#speed').onchange=()=>{if(playing){clearTimeout(playTimer);tick();}};$('#month-slider').oninput=ev=>{stopPlay();state.timeMode='month';change('month',C.FIRST_MONTH+Number(ev.target.value));};
    for(const[id,step]of [['previous',-1],['next',1]])$('#'+id).onclick=()=>{stopPlay();const wasAll=state.timeMode==='all';state.timeMode='month';change('month',Math.max(C.FIRST_MONTH,Math.min(C.LAST_MONTH,wasAll?C.FIRST_MONTH:state.month+step)));};
    $('#date-button').onclick=()=>{stopPlay();$('#date-year').value=String(Math.floor(state.month/12));$('#date-month').value=String(state.month%12);showDialog($('#date-dialog'));};$('#date-form').onsubmit=ev=>{ev.preventDefault();state.timeMode='month';state.month=Math.min(C.LAST_MONTH,Math.max(C.FIRST_MONTH,Number($('#date-year').value)*12+Number($('#date-month').value)));closeDialog($('#date-dialog'));render();};$('#all-years').onclick=()=>{closeDialog($('#date-dialog'));change('timeMode','all');};
    $('#sort').onchange=ev=>{sort=ev.target.value;pageNumber=0;renderDataset();};$('#data-previous').onclick=()=>{pageNumber--;renderDataset();$('.data-browser').scrollIntoView({block:'start'});};$('#data-next').onclick=()=>{pageNumber++;renderDataset();$('.data-browser').scrollIntoView({block:'start'});};$('#coverage-view').onchange=renderCoverage;
    $$('dialog').forEach(d=>{d.addEventListener('cancel',ev=>{ev.preventDefault();closeDialog(d);});d.addEventListener('click',ev=>{if(ev.target!==d)return;const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog(d);});});
    document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPlay();});window.addEventListener('resize',()=>{if(state.page==='map')AtlasMap.invalidate();});
  }
  try{
    const responses=await Promise.all([fetch('data/atlas.json'),fetch('data/methods.json')]);if(responses.some(r=>!r.ok))throw Error('The data file could not be loaded.');[data,methods]=await Promise.all(responses.map(r=>r.json()));countryMap=new Map(data.countries.map(c=>[c.country_code,c]));if(methods.version!==data.meta.release)throw Error('The register and methods name different releases.');renderReleaseMetadata();
    $('#mechanism').insertAdjacentHTML('beforeend',[...new Set([...data.events,...data.collective].map(r=>r.mechanism))].sort((a,b)=>(C.mechanisms[a]?.[0]||a).localeCompare(C.mechanisms[b]?.[0]||b)).map(k=>'<option value="'+e(k)+'">'+e(C.mechanisms[k]?.[0]||k.replaceAll('_',' '))+'</option>').join(''));
    $('#subregion').insertAdjacentHTML('beforeend',[...new Set(data.countries.map(c=>c.subregion).filter(Boolean))].sort().map(r=>'<option>'+e(r)+'</option>').join(''));
    for(const id of ['scenario','analysis-scenario'])$('#'+id).innerHTML=data.sensitivity.scenarios.map(s=>'<option value="'+e(s.key)+'">'+e(s.label)+'</option>').join('');$('#analysis-region').innerHTML=regionNames.map(r=>'<option>'+r+'</option>').join('');$('#date-year').innerHTML=Array.from({length:11},(_,i)=>'<option>'+String(2016+i)+'</option>').join('');$('#date-month').innerHTML=Array.from({length:12},(_,i)=>'<option value="'+i+'">'+new Intl.DateTimeFormat('en-GB',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2020,i,1)))+'</option>').join('');
    const p=new URLSearchParams(location.search);for(const k of Object.keys(defaults))if(p.has(k))state[k]=p.get(k);state.month=Math.max(C.FIRST_MONTH,Math.min(C.LAST_MONTH,Number(state.month)||C.FIRST_MONTH));if(!regionNames.includes(state.region))state.region='World';if(!['map','overview','analysis','dataset'].includes(state.page))state.page='map';if(!['handovers','collective'].includes(state.series))state.series='handovers';if(!['all','year','month'].includes(state.timeMode))state.timeMode='all';if(!['count','mechanism','coverage'].includes(state.colourBy))state.colourBy=defaults.colourBy;if(!data.sensitivity.scenarios.some(s=>s.key===state.scenario))state.scenario='main';if(state.country&&!countryMap.has(state.country))state.country='';
    await AtlasMap.init({countries:data.countries,onCountry:openCountry});AtlasMap.setRegion(state.region);attach();renderOverview();$('#loading').hidden=true;navigate(state.page);if(p.get('case'))openCountry(p.get('case'));if(p.get('record'))openRecord(p.get('record'));
  }catch(err){console.error(err);$('#loading').innerHTML='<h2>The atlas could not open</h2><p>The map or register did not finish loading. Reload the page to try again.</p><p style="margin-top:14px"><a href="data/events.csv" download>Download the handover register</a></p><button class="quiet" id="retry" style="margin-top:15px">Try again</button>';$('#retry').onclick=()=>location.reload();}
})();
